package ama.meeting;
import ama.db.TransactionRunner;import ama.task.JdbcSubjectFences;import ama.minutes.ControlledMinutesDataSource;import ama.contract.IdentityContracts.*;import java.nio.file.*;import java.util.*;import java.sql.*;import java.lang.reflect.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import com.fasterxml.jackson.databind.ObjectMapper;
/** Actual production identity prelock reader with one temporary local source name; always restores it. */
public final class LocalIdentityNameReadCheck {
 static final String PERSON="dev-viewer";
 static final class Source extends AbstractDataSource {
  final DataSource delegate;boolean observe;int targetRawQueries,targetLargeReads;Source(DataSource delegate){this.delegate=delegate;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> type,InvocationHandler h){return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},h);}
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object result=invoke(actual,m,a);if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&result instanceof PreparedStatement statement){var bound=new HashMap<Integer,Object>();return proxy(statement,PreparedStatement.class,(s,sm,sa)->{
    if(sm.getName().startsWith("set")&&sa!=null&&sa.length>=2&&sa[0] instanceof Integer index)bound.put(index,sa[1]);
    if(observe&&sm.getName().equals("executeQuery")&&PERSON.equals(bound.get(1))&&sql.contains(" FROM enterprise_identity ")){String projection=sql.substring(0,sql.indexOf(" FROM ")).replaceAll("(?i)OCTET_LENGTH\\(CONVERT\\(display_name USING utf16\\)\\)","0").replaceAll("(?i)(OCTET_LENGTH|CHAR_LENGTH)\\(display_name\\)","0");if(projection.matches("(?is).*\\bdisplay_name\\b.*")||projection.contains("*"))targetRawQueries++;}
    Object value=invoke(statement,sm,sa);if(observe&&sm.getName().equals("executeQuery")&&PERSON.equals(bound.get(1))&&value instanceof ResultSet rows)return proxy(rows,ResultSet.class,(r,rm,ra)->{Object field=invoke(rows,rm,ra);if(rm.getName().equals("getString")&&field instanceof String text&&text.length()>100000)targetLargeReads++;return field;});return value;
   });}return result;});}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==1,"Explicit daily check required");Path file=Path.of(args[0]).toRealPath();check(file.getParent().endsWith(Path.of(".tools/local-app"))&&Files.size(file)<65536,"Daily configuration required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned local DB required");var source=new Source(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")));var j=new JdbcTemplate(source);j.setQueryTimeout(5);var tx=new TransactionRunner(source,30);var access=new JdbcMeetingAccess(source,tx,new JdbcSubjectFences(source,Set.of("MEETING")));var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));String original=j.queryForObject("SELECT display_name FROM enterprise_identity WHERE enterprise_id=? AND status='ACTIVE'",String.class,PERSON),wide="界🧪".repeat(1200000);boolean budgetRejected=false;
  try{check(j.update("UPDATE enterprise_identity SET display_name=? WHERE enterprise_id=? AND status='ACTIVE'",wide,PERSON)==1,"Exact test identity");source.observe=true;try{tx.required(()->{access.lockIdentities(actor,List.of(PERSON));return null;});}catch(WorkspaceReadBudget.Unavailable expected){budgetRejected=true;}}
  finally{source.observe=false;check(j.update("UPDATE enterprise_identity SET display_name=? WHERE enterprise_id=?",original,PERSON)==1,"Exact identity restore required");}
  int wideQueries=source.targetRawQueries,wideReads=source.targetLargeReads;var measured=new WorkspaceReadBudget();tx.required(()->{var names=access.lockIdentities(actor,List.of(PERSON),measured);check(original.equals(names.people.get(PERSON).name()),"Normal native Unicode name must remain exact");return null;});var usage=measured.usage();var d=WorkspaceReadBudget.DEFAULT;
  var exactLimits=new WorkspaceReadBudget.Limits(usage.bytes(),d.responseBytes(),usage.scalars(),usage.units(),usage.rows(),usage.edges(),d.timeout());tx.required(()->{access.lockIdentities(actor,List.of(PERSON),new WorkspaceReadBudget(exactLimits,()->false));return null;});
  source.targetRawQueries=0;source.targetLargeReads=0;source.observe=true;boolean minusOne=false,cancelled=false;
  try{var under=new WorkspaceReadBudget.Limits(usage.bytes()-1,d.responseBytes(),usage.scalars(),usage.units(),usage.rows(),usage.edges(),d.timeout());try{tx.required(()->{access.lockIdentities(actor,List.of(PERSON),new WorkspaceReadBudget(under,()->false));return null;});}catch(WorkspaceReadBudget.Unavailable expected){minusOne=true;}check(source.targetRawQueries==0,"Cumulative less-one budget must reject before target name query");try{tx.required(()->{access.lockIdentities(actor,List.of(PERSON),new WorkspaceReadBudget(d,()->true));return null;});}catch(WorkspaceReadBudget.Unavailable expected){cancelled=true;}check(source.targetRawQueries==0,"Cancellation must precede target name query");}finally{source.observe=false;}
  boolean restored=original.equals(j.queryForObject("SELECT display_name FROM enterprise_identity WHERE enterprise_id=?",String.class,PERSON));boolean pass=budgetRejected&&wideQueries==0&&wideReads==0&&restored&&minusOne&&cancelled;System.out.println(new ObjectMapper().writeValueAsString(Map.of("pass",pass,"defaultBytes",WorkspaceReadBudget.DEFAULT.bytes(),"sourceNameUtf8",8400000,"budgetRejected",budgetRejected,"targetRawQueries",wideQueries,"targetLargeStringReads",wideReads,"normalUnicodeAndExactBudget",true,"cumulativeLessOneBeforeName",minusOne,"cancelBeforeName",cancelled,"identityRestored",restored)));if(!pass)System.exit(1);
 }
}
